@startuml

class Family {
  + NameOfFamilyHead
  + Address
  + Telephone
  + InsuranceCarrier
  + PolicyNumber
}

class Patient {
  + Name
  + Information
}

class Doctor {
  + Name
  + Specialty
  + Address
  + Telephone
  + PagerNumber
  + SSN
}

class Appointment {
  + Date
  + Time
  + Reason
}

class Visit {
  + Diagnosis
  + Treatment
}

class Medication {
  + Name
}

Family "1" -- "1..*" Patient : has
Family "1" -- "0..1" Doctor : hasPrimaryCare
Patient "1" -- "*" Appointment : has
Patient "1" -- "*" Visit : undergoes
Doctor "0..*" -- "*" Visit : sees
Visit "1" -- "0..*" Medication : prescribes

@enduml

